using Microsoft.Win32; namespace PhotoBooth.Admin.UI.Services { public sealed class FileDialogService:IFileDialogService { public string PickPng(){var dialog=new OpenFileDialog{Filter="PNG frames (*.png)|*.png",CheckFileExists=true,Multiselect=false};return dialog.ShowDialog()==true?dialog.FileName:null;} public string PickBackground(){var dialog=new OpenFileDialog{Filter="Images and GIF (*.png;*.jpg;*.jpeg;*.bmp;*.gif)|*.png;*.jpg;*.jpeg;*.bmp;*.gif",CheckFileExists=true,Multiselect=false};return dialog.ShowDialog()==true?dialog.FileName:null;} public string PickCube(){var dialog=new OpenFileDialog{Filter="3D cube LUT (*.cube)|*.cube",CheckFileExists=true,Multiselect=false};return dialog.ShowDialog()==true?dialog.FileName:null;} public string PickFolder(string initialPath){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{SelectedPath=initialPath??string.Empty,ShowNewFolderButton=true})return dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK?dialog.SelectedPath:null;} } }
